;------------------------------------------------------------------------------
; CmdYell: Y, "Yell, whom?". Asks a player and a word (9 characters). EVOCARE said by
; a player with the Mark of the Snake, on Sosaria at x = 0Ah, y = 38h or 3Bh, carries the
; party past the Great Serpent (y 38h <-> 3Bh). Anything else: "No effect!".
; In: SI = the prompt. Ends at MainLoop.
;------------------------------------------------------------------------------
CmdYell:	call PrintMsg	;@7458
	call AskPlayer	;@745B
	je CmdYell_Done	;@745E
	call IsUp	;@7460
	jne CmdYell_Incap	;@7463
	lea si, MsgWord	; "Word: "	;@7465
	call PrintMsg	;@7469
	push bx	;@746C
	sub sp, 9	; a 9-character buffer on the stack	;@746D
	mov cx, 9	;@7470
	mov di, sp	;@7473
	call ReadLine	;@7475
	mov cx, bx	;@7478
	call ScrollMsg	;@747A
	call UpcaseBuf	;@747D
	lea si, WordEvocare	; "EVOCARE"	;@7480
	call MatchWord	;@7484
	add sp, 9	;@7487
	pop bx	;@748A
	cmp al, 0FFh	;@748B
	jne CmdYell_NoEffect	;@748D
	mov al, byte ptr [bx+0Eh]	; marks	;@748F
	and al, 40h	; Mark of the Snake	;@7492
	je CmdYell_NoEffect	;@7494
	cmp byte ptr Location, 0	; Sosaria	;@7496
	jne CmdYell_NoEffect	;@749B
	cmp byte ptr PlayerXY, 0Ah	; x	;@749D
	jne CmdYell_NoEffect	;@74A2
	cmp byte ptr PlayerY, 38h	; y: one side of the serpent	;@74A4
	je CmdYell_Serpent	;@74A9
	cmp byte ptr PlayerY, 3Bh	; the other side	;@74AB
	jne CmdYell_NoEffect	;@74B0
CmdYell_Serpent:	xor byte ptr PlayerY, 3	; 38h <-> 3Bh	;@74B2
	call ClearView	;@74B7
	mov al, 0FDh	; ? a sound with parameters BL, BH	;@74BA
	mov bl, 0C0h	;@74BC
	mov bh, 40h	;@74BE
	call Sound	;@74C0
	call BuildView	;@74C3
CmdYell_Done:	jmp MainLoop	;@74C6
CmdYell_Incap:	jmp MsgIncapacitated	;@74C9
CmdYell_NoEffect:	lea si, MsgNoEffect	; "No effect!"	;@74CC
	call PrintMsg	;@74D0
	jmp CmdYell_Done	;@74D3
;------------------------------------------------------------------------------
; CmdOther: O, "Other command!/Whose action?". Asks a player and a command word (10
; characters), looks it up in the list of word pointers at 6540 (INSERT, DIG, SEARCH, BRIBE,
; PRAY, 0) and jumps to the handler at the same place in 654C, with DI = the player's record
; and BP = his number 0-3. An unknown word: "No effect!". In: SI = the prompt.
;------------------------------------------------------------------------------
CmdOther:	call PrintMsg	;@74D5
	call AskPlayer	;@74D8
	je CmdOther_Done	;@74DB
	dec al	;@74DD
	mov bp, ax	; BP = player 0-3 (AH: whatever it was)	;@74DF
	mov dx, bx	;@74E1
	call IsUp	;@74E3
	jne CmdYell_Incap	;@74E6
	lea si, MsgCmd	; "Cmd: "	;@74E8
	call PrintMsg	;@74EC
	sub sp, 0Ah	; a 10-character buffer on the stack	;@74EF
	mov cx, 0Ah	;@74F2
	mov di, sp	;@74F5
	call ReadLine	;@74F7
	mov cx, bx	;@74FA
	call ScrollMsg	;@74FC
	call UpcaseBuf	;@74FF
	mov bx, 0	;@7502
CmdOther_Find:	mov si, word ptr OtherWords[bx]	; the words	;@7505
	test si, 0FFFFh	; 0 ends the list	;@7509
	je CmdOther_Found	;@750D
	call MatchWord	;@750F
	cmp al, 0FFh	;@7512
	je CmdOther_Found	;@7514
	add bx, 2	;@7516
	jmp CmdOther_Find	;@7519
CmdOther_Found:	add sp, 0Ah	;@751B
	test si, 0FFFFh	;@751E
	jne CmdOther_Go	;@7522
	lea si, MsgNoEffect	; "No effect!"	;@7524
	call PrintMsg	;@7528
CmdOther_Done:	jmp MainLoop	;@752B
CmdOther_Go:	mov di, dx	; DI = the record	;@752E
	jmp word ptr OtherCmds[bx]	; the handlers	;@7530
;------------------------------------------------------------------------------
; CmdDig: Other DIG. On Sosaria at (21h, 03h) the party finds the Exotic weapon (one
; more in record byte 3Fh, flags 14C8 and 14CA set to 0FFh: the weapon menus get all their
; entries), at (13h, 2Ch) the Exotic armour (2Fh; flags 14C9, 14CB): "Exotics!".
; In: DI = the record.
;------------------------------------------------------------------------------
CmdDig:	cmp byte ptr Location, 0	; Sosaria	;@7534
	jne CmdDig_Nothing	;@7539
	mov ax, word ptr PlayerXY	; AL = x, AH = y	;@753B
	mov si, 0Eh	; PartyTile+0Eh = ExoticWeaponFound	;@753E
	mov bx, 3Fh	; weapon 15, Exotic	;@7541
	cmp ax, 321h	; x 21h, y 3	;@7544
	je CmdDig_Found	;@7547
	mov si, 0Fh	; ExoticArmourFound	;@7549
	mov bx, 2Fh	; armour 7, Exotic	;@754C
	cmp ax, 2C13h	; x 13h, y 2Ch	;@754F
	je CmdDig_Found	;@7552
CmdDig_Nothing:	lea si, MsgNoEffect	; "No effect!"	;@7554
	call PrintMsg	;@7558
CmdDig_Done:	jmp MainLoop	;@755B
CmdDig_Found:	mov al, byte ptr [bx+di]	;@755E
	add al, 1	;@7560
	daa	;@7562
	mov byte ptr [bx+di], al	;@7563
	jae CmdDig_Flags	;@7565
	mov byte ptr [bx+di], 99h	; at most 99	;@7567
CmdDig_Flags:	mov byte ptr PartyTile[si], 0FFh	; Weapon/ExoticArmourFound	;@756A
	add si, 2	;@756F
	mov byte ptr PartyTile[si], 0FFh	; Weapon/ExtraArmoursOk	;@7572
	lea si, MsgExotics	; "Exotics!"	;@7577
	call PrintMsg	;@757B
	jmp CmdDig_Done	;@757E
;------------------------------------------------------------------------------
; CmdPray: Other PRAY. In the towne entered from x = 22h (Location 2: a towne), at
; (30h): "Yell 'Evocare'". Elsewhere "No effect!".
;------------------------------------------------------------------------------
CmdPray:	cmp byte ptr Location, 2	;@7580
	jne CmdPray_Nothing	;@7585
	cmp byte ptr PartyXY, 22h	; the entrance's x on Sosaria	;@7587
	jne CmdPray_Nothing	;@758C
	cmp word ptr PlayerXY, 3030h	; x 30h, y 30h	;@758E
	jne CmdPray_Nothing	;@7594
	lea si, MsgYellEvocare	; "Yell 'Evocare'"	;@7596
	call PrintMsg	;@759A
	jmp short CmdPray_Done	;@759D
CmdPray_Nothing:	lea si, MsgNoEffect	; "No effect!"	;@759F
	call PrintMsg	;@75A3
CmdPray_Done:	jmp MainLoop	;@75A6
;------------------------------------------------------------------------------
; CmdBribe: Other BRIBE. Asks a direction; a guard there (creature tile 48h = shape
; 18) takes 100 gold from the player and leaves: his slot is cleared and the map cell gets
; MonUnder's byte back (so MonUnder holds the tile under the creature ?). Too little gold:
; "Not enough gold!". In: DI = the record.
;------------------------------------------------------------------------------
CmdBribe:	lea si, MsgOtherDirect	; "Direct? "	;@75A9
	call PrintMsg	;@75AD
	call AskDirection	;@75B0
	je CmdBribe_Done	;@75B3
	mov dx, bx	;@75B5
	call FindMonster	;@75B7
	cmp bx, -1	;@75BA
	je CmdBribe_NoEffect	;@75BD
	cmp byte ptr MonTile[bx], 48h	; guard	;@75BF
	jne CmdBribe_NoEffect	;@75C4
	mov ax, word ptr [di+23h]	; gold	;@75C6
	xchg al, ah	;@75C9
	sub al, 1	; - 100 (the high BCD byte)	;@75CB
	das	;@75CD
	xchg al, ah	;@75CE
	jb CmdBribe_NoGold	;@75D0
	mov word ptr [di+23h], ax	;@75D2
	mov ah, byte ptr MonUnder[bx]	;@75D5
	mov dh, byte ptr MonY[bx]	;@75D9
	mov dl, byte ptr MonX[bx]	;@75DD
	mov byte ptr MonTile[bx], 0	; the slot is free	;@75E1
	mov bx, dx	;@75E6
	call MapCellAddr	;@75E8
	mov byte ptr [bx], ah	;@75EB
	jmp short CmdBribe_Done	;@75ED
CmdBribe_NoEffect:	lea si, MsgNoEffect	; "No effect!"	;@75EF
	call PrintMsg	;@75F3
CmdBribe_Done:	jmp MainLoop	;@75F6
CmdBribe_NoGold:	lea si, MsgNotEnoughGold	; "Not enough gold!"	;@75F9
	call PrintMsg	;@75FD
	mov al, 0FFh	;@7600
	call Sound	;@7602
	jmp CmdBribe_Done	;@7605
;------------------------------------------------------------------------------
; CmdSearch: Other SEARCH. Standing on a shrine (TileHere = shape 3Eh; the shrines of
; Ambrosia) the player gets the card 1 << (x & 3): bit 0 Love, 1 Sol, 2 Moons, 3 Death
; (record byte 0Eh): "A card, with strange marks!". In: DI = the record.
;------------------------------------------------------------------------------
CmdSearch:	cmp byte ptr TileHere, 3Eh	; shrine	;@7607
	jne CmdSearch_Nothing	;@760C
	mov cl, byte ptr PlayerXY	; x	;@760E
	and cl, 3	;@7612
	mov al, 1	;@7615
	shl al, cl	;@7617
	or byte ptr [di+0Eh], al	; cards	;@7619
	lea si, MsgStrangeCard	; "A card, with strange marks!"	;@761C
	call PrintMsg	;@7620
	jmp short CmdSearch_Done	;@7623
CmdSearch_Nothing:	lea si, MsgNoEffect	; "No effect!"	;@7625
	call PrintMsg	;@7629
CmdSearch_Done:	jmp MainLoop	;@762C
;------------------------------------------------------------------------------
; CmdInsert: Other INSERT, the end of the game. Asks a direction: it must be a panel
; of Exodus (map byte 7Ch = shape 31) and a card (D, S, L, M). The cards go in one at a time
; (CardsInserted counts them, reset by the main loop at 1E04): card n must be at x = 1Eh + n and be
; Love, Sol, Moons, Death in that order (CardOrder "LSMD"), and the player must own card bit n,
; else "No effect!". Right: the panel flashes (shape 60, Magic) and becomes floor; the fourth
; one jumps to the ending (EndGame). Wrong place or card: the player dies.
; In: DI = the record, BP = the player 0-3.
;------------------------------------------------------------------------------
CmdInsert:	lea si, MsgOtherDirect	; "Direct? "	;@762F
	call PrintMsg	;@7633
	call AskDirection	;@7636
	jne CmdInsert_Cell	;@7639
	jmp CmdInsert_Done	;@763B
CmdInsert_Cell:	mov cl, bl	; CL = the target's x	;@763E
	call MapCellAddr	;@7640
	cmp al, 7Ch	; Exodus (shape 31)	;@7643
	je CmdInsert_Exodus	;@7645
	jmp CmdInsert_NoEffect	;@7647
CmdInsert_Exodus:	push bx	;@764A
	push cx	;@764B
	lea si, MsgCardMenu	; "D, S, L, M:"	;@764C
	call PrintMsg	;@7650
	push di	;@7653
	lea si, CardNames	; the card names	;@7654
	mov cx, 6	;@7658
	lea di, CardKeys	; keys M D L S Q Esc	;@765B
	call AskChoice	;@765F
	pop di	;@7662
	pop cx	;@7663
	pop si	; SI = the map cell	;@7664
	call ScrollMsg	;@7665
	cmp al, 51h	; 'Q'	;@7668
	je CmdInsert_Done	;@766A
	cmp al, 1Bh	; Esc	;@766C
	je CmdInsert_Done	;@766E
	mov bx, word ptr CardsInserted	; cards in so far	;@7670
	mov ch, cl	;@7674
	mov ah, 1	;@7676
	mov cl, bl	;@7678
	shl ah, cl	;@767A
	test byte ptr [di+0Eh], ah	; owns card bit n?	;@767C
	je CmdInsert_NoEffect	;@767F
	mov ah, bl	;@7681
	add ah, 1Eh	;@7683
	cmp ah, ch	; x = 1Eh + n?	;@7686
	jne CmdInsert_Wrong	;@7688
	cmp al, byte ptr CardOrder[bx]	; "LSMD"[n]?	;@768A
	jne CmdInsert_Wrong	;@768E
	inc word ptr CardsInserted	;@7690
	mov cx, 5	;@7694
CmdInsert_Flash:	mov byte ptr [si], 0F0h	; shape 60 (Magic)	;@7697
	call BuildView	;@769A
	mov al, 0F7h	;@769D
	call Sound	;@769F
	mov byte ptr [si], 7Ch	; Exodus	;@76A2
	call BuildView	;@76A5
	mov al, 0F7h	;@76A8
	call Sound	;@76AA
	loop CmdInsert_Flash	;@76AD
	mov byte ptr [si], 20h	; floor (shape 8)	;@76AF
	call BuildView	;@76B2
	cmp word ptr CardsInserted, 4	;@76B5
	jne CmdInsert_Done	;@76BA
	jmp EndGame	; all four: the ending	;@76BC
CmdInsert_NoEffect:	lea si, MsgNoEffect	; "No effect!"	;@76BF
	call PrintMsg	;@76C3
CmdInsert_Done:	jmp MainLoop	;@76C6
CmdInsert_Wrong:	mov ax, bp	;@76C9
	call FlashPlayer	;@76CB
	mov al, 0F7h	;@76CE
	call Sound	;@76D0
	mov ax, bp	;@76D3
	call FlashPlayer	;@76D5
	mov word ptr [di+1Ah], 0	; hit points 0 ...	;@76D8
	mov bx, di	;@76DD
	mov al, 0FFh	; ... minus 0FFh: dead	;@76DF
	call HurtPlayer	;@76E1
	jmp CmdInsert_Done	;@76E4
	db 0h,0h,0h,0h,0h,0h,0h,0h,0h,0h	; unused	;@76E6
; The dungeon step by Facing (0 north, 1 east, 2 south, 3 west): x, then y. Used by DUNMOVE.
FacingDxTbl label byte
	db 0h,1h,0h,0FFh	;@76F0
FacingDyTbl label byte
	db 0FFh,0h,1h,0h	;@76F4
; The handlers of the special dungeon cells 1-8 (DUNMOVE 83F0; 7 is never dispatched): time
; vision, fountain, strange wind, trap, ... (DUNEVENT).
DungeonEventCmds	dw EventTimeVision	;@76F8
	dw EventFountain	;@76FA
	dw EventWind	;@76FC
	dw EventTrap	;@76FE
	dw EventRod	;@7700
	dw EventGremlins	;@7702
	dw 0h	;@7704
	dw EventWriting	;@7706
; The dungeon command table (docs/MAP.md "The command tables"): 33 key words (character, scan
; code; 0 = an extended key), then 33 handlers and 33 prompts in the same order. Space C G H
; I J M N O R V W Y Z Alt-S Alt-V act as on the surface; B A E F L Q T X S answer "Not a DNG
; cmd!" (8472); K Klimb, D Descend, Right and Left turn, Up Advance, Down Retreat, P Peer.
DungeonKeys label byte
	db 20h,39h,43h,2Eh,47h,22h,48h,23h,49h,17h,4Ah,24h,4Dh,32h,4Eh,31h	;@7708
	db 4Fh,18h,52h,13h,56h,2Fh,57h,11h,59h,15h,5Ah,2Ch,0h,1Fh,0h,2Fh	;@7718
	db 42h,30h,41h,1Eh,45h,12h,46h,21h,4Ch,26h,51h,10h,54h,14h,55h,16h	;@7728
	db 58h,2Dh,4Bh,25h,44h,20h,0h,4Dh,0h,4Bh,53h,1Fh,0h,48h,0h,50h	;@7738
	db 50h,19h	;@7748
